INSERT INTO `books` (`id`, `title`, `slug`, `category_id`, `publisher_id`, `ddc_class_id`, `publication_year`, `isbn`, `language`, `synopsis`, `shelf_location`, `cover_image`, `popularity`, `created_at`, `updated_at`, `ebook_file_path`, `is_ebook`) VALUES (1, 'Laskar Pelangi', 'laskar-pelangi', 1, 1, 9, 2005, '978-979-3062-79-2', 'Indonesia', 'Kisah perjuangan sepuluh anak di Gantong, Pulau Belitong, dalam menempuh pendidikan dengan keterbatasan fasilitas di bawah bimbingan guru yang penuh dedikasi.', 'Rak F-12', 'https://images.unsplash.com/photo-1544947950-fa07a98d237f?auto=format&fit=crop&w=700&q=80', 98, '2026-09-08 13:32:22', '2026-09-08 13:32:22', NULL, 0) ON DUPLICATE KEY UPDATE id=id;
INSERT INTO `books` (`id`, `title`, `slug`, `category_id`, `publisher_id`, `ddc_class_id`, `publication_year`, `isbn`, `language`, `synopsis`, `shelf_location`, `cover_image`, `popularity`, `created_at`, `updated_at`, `ebook_file_path`, `is_ebook`) VALUES (2, 'Tenggelamnya Kapal Van der Wijck', 'tenggelamnya-kapal-van-der-wijck', 1, 3, 9, 1938, '978-979-407-123-4', 'Indonesia', 'Mahakarya Buya Hamka yang mengisahkan cinta sejati antara Zainuddin dan Hayati yang terhalang oleh adat istiadat dan strata sosial di tanah Minangkabau.', 'Rak F-04', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?auto=format&fit=crop&w=700&q=80', 95, '2026-09-08 13:32:22', '2026-09-08 13:32:22', NULL, 0) ON DUPLICATE KEY UPDATE id=id;
INSERT INTO `books` (`id`, `title`, `slug`, `category_id`, `publisher_id`, `ddc_class_id`, `publication_year`, `isbn`, `language`, `synopsis`, `shelf_location`, `cover_image`, `popularity`, `created_at`, `updated_at`, `ebook_file_path`, `is_ebook`) VALUES (3, 'Bumi Manusia', 'bumi-manusia', 1, 2, 9, 1980, '978-979-97312-3-4', 'Indonesia', 'Buku pertama dari Tetralogi Buru. Menampilkan perjuangan Minke, seorang pribumi cerdas di era Hindia Belanda yang memperjuangkan martabat bangsanya.', 'Rak F-08', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?auto=format&fit=crop&w=700&q=80', 92, '2026-09-08 13:32:22', '2026-09-08 13:32:22', NULL, 0) ON DUPLICATE KEY UPDATE id=id;
INSERT INTO `books` (`id`, `title`, `slug`, `category_id`, `publisher_id`, `ddc_class_id`, `publication_year`, `isbn`, `language`, `synopsis`, `shelf_location`, `cover_image`, `popularity`, `created_at`, `updated_at`, `ebook_file_path`, `is_ebook`) VALUES (4, 'Negeri 5 Menara', 'negeri-5-menara', 1, 2, 9, 2009, '978-979-22-4861-6', 'Indonesia', 'Enam santri dari berbagai pelosok Nusantara yang disatukan di Pondok Madani dengan mantra penggerak impian hidup: Man Jadda Wajada.', 'Rak F-15', 'https://images.unsplash.com/photo-1543002588-bfa74002ed7e?auto=format&fit=crop&w=700&q=80', 88, '2026-09-08 13:32:22', '2026-09-08 13:32:22', NULL, 0) ON DUPLICATE KEY UPDATE id=id;
INSERT INTO `books` (`id`, `title`, `slug`, `category_id`, `publisher_id`, `ddc_class_id`, `publication_year`, `isbn`, `language`, `synopsis`, `shelf_location`, `cover_image`, `popularity`, `created_at`, `updated_at`, `ebook_file_path`, `is_ebook`) VALUES (5, 'Atomic Habits', 'atomic-habits', 4, 2, 2, 2018, '978-602-06-3317-6', 'Indonesia', 'Panduan praktis teruji untuk membentuk kebiasaan baik, memutus kebiasaan buruk, dan menguasai perilaku kecil yang menghasilkan lonjakan prestasi.', 'Rak P-02', 'https://images.unsplash.com/photo-1589829085413-56de8ae18c73?auto=format&fit=crop&w=700&q=80', 99, '2026-09-08 13:32:22', '2026-09-08 13:32:22', NULL, 0) ON DUPLICATE KEY UPDATE id=id;
INSERT INTO `books` (`id`, `title`, `slug`, `category_id`, `publisher_id`, `ddc_class_id`, `publication_year`, `isbn`, `language`, `synopsis`, `shelf_location`, `cover_image`, `popularity`, `created_at`, `updated_at`, `ebook_file_path`, `is_ebook`) VALUES (6, 'Bumi', 'bumi', 1, 2, 9, 2014, '978-602-03-0112-9', 'Indonesia', 'Awal mula perjalanan luar biasa Raib, Seli, dan Ali menembus klan Bulan serta mengungkap rahasia peradaban paralel yang tersembunyi di alam semesta.', 'Rak F-19', 'https://images.unsplash.com/photo-1532012164546-f432f2e37b29?auto=format&fit=crop&w=700&q=80', 86, '2026-09-08 13:32:22', '2026-09-08 13:32:22', NULL, 0) ON DUPLICATE KEY UPDATE id=id;
INSERT INTO `books` (`id`, `title`, `slug`, `category_id`, `publisher_id`, `ddc_class_id`, `publication_year`, `isbn`, `language`, `synopsis`, `shelf_location`, `cover_image`, `popularity`, `created_at`, `updated_at`, `ebook_file_path`, `is_ebook`) VALUES (7, 'Fisika untuk SMA/MA Kelas XI (Kurikulum Merdeka)', 'fisika-untuk-smama-kelas-xi-kurikulum-merdeka', 5, 4, 6, 2023, '978-623-180-201-9', 'Indonesia', 'Materi ajar fisika komprehensif berlandaskan saintifik, dilengkapi eksperimen laboratorium, fenomena mekanika, termodinamika, dan gelombang elektromagnetik.', 'Rak S-03', 'https://images.unsplash.com/photo-1636466497217-26a8cbeaf0aa?auto=format&fit=crop&w=700&q=80', 82, '2026-09-08 13:32:22', '2026-09-08 13:32:22', NULL, 0) ON DUPLICATE KEY UPDATE id=id;
